// STUB — Phase 8 Skeleton
// PURPOSE: Load Brand Brain data for Vị Cuốn
// PRODUCTION: Read from brand-brain/vi-cuon.md or Google Sheets / Supabase
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL

const inputData = $input.first().json;

const brandBrain = {
  brand_name: inputData.brand_name || 'Vị Cuốn',
  brand_positioning: 'REPLACE_WITH_BRAND_POSITIONING',
  target_customer: 'REPLACE_WITH_TARGET_CUSTOMER',
  menu_items: 'REPLACE_WITH_MENU_ITEMS',
  price_range: 'REPLACE_WITH_PRICE_RANGE',
  address: 'REPLACE_WITH_ADDRESS',
  opening_hours: 'REPLACE_WITH_OPENING_HOURS',
  key_offers: 'REPLACE_WITH_KEY_OFFERS',
  tone_of_voice: 'REPLACE_WITH_TONE_OF_VOICE',
  forbidden_claims: 'REPLACE_WITH_FORBIDDEN_CLAIMS',
  approval_status: 'REPLACE_WITH_APPROVAL_STATUS'
};

return [{ json: { ...inputData, brandBrain, brandBrainLoaded: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Detect customer message intent and sentiment
// PRODUCTION: HTTP Request to Claude API or equivalent classifier
// CREDENTIAL NEEDED: REPLACE_WITH_ANTHROPIC_API_KEY
// CONSTRAINT: No real API call in skeleton. Returns mock detection.
// ESCALATION RULES (from schemas/comment-inbox-reply.schema.json):
//   escalation_required=true for: Complaint, Sensitive/Legal, Angry sentiment
//   For escalated cases: draft_reply MUST be null (never generate a draft)

const inputData = $input.first().json;
const message = inputData.customer_message || '';

// Stub intent detection — production would call AI classifier
// Default to safe values that require review
const detected_intent = 'Other';  // Replace with AI-detected intent
const sentiment = 'Neutral';       // Replace with AI-detected sentiment

// Escalation logic — must match schema escalation_required rule
// Real production: detected_intent in ['Complaint', 'Sensitive / Legal'] OR sentiment == 'Angry'
const escalationIntents = ['Complaint', 'Sensitive / Legal'];
const escalationSentiments = ['Angry'];

const escalation_required = (
  escalationIntents.includes(detected_intent) ||
  escalationSentiments.includes(sentiment)
);

const escalation_reason = escalation_required
  ? `Escalated: intent=${detected_intent}, sentiment=${sentiment}. Owner must handle directly.`
  : null;

// draft_reply MUST be null if escalation_required
const draft_reply_placeholder = escalation_required ? null : 'PENDING_GENERATION';

return [{
  json: {
    ...inputData,
    detected_intent,
    sentiment,
    escalation_required,
    escalation_reason,
    draft_reply: draft_reply_placeholder,
    intentDetectionCompleted: true
  }
}];

// STUB — Phase 8 Skeleton
// PURPOSE: Call AI model to generate reply draft for non-escalated messages
// PRODUCTION: HTTP Request to Claude API (claude-sonnet-4-6) with Brand Brain + intent context
// CREDENTIAL NEEDED: REPLACE_WITH_ANTHROPIC_API_KEY
// CONSTRAINT: No real API call in skeleton. Returns mock reply draft.
// SCHEMA: Output must conform to schemas/comment-inbox-reply.schema.json
// CRITICAL: human_review_required is ALWAYS true (schema const: true)
// CRITICAL: Only called for non-escalated messages (escalation_required=false)

const inputData = $input.first().json;

// Mock reply draft — conforms to comment-inbox-reply.schema.json
const replyDraft = {
  reply_id: 'IR-VQ-STUB-001',
  brand_id: inputData.brand_id || 'VQ',
  brand_name: inputData.brand_name || 'Vị Cuốn',
  channel: inputData.channel || 'Facebook Comment',
  customer_message: inputData.customer_message || 'REPLACE_WITH_VERBATIM_CUSTOMER_MESSAGE',
  detected_intent: inputData.detected_intent || 'Other',
  sentiment: inputData.sentiment || 'Neutral',
  draft_reply: 'STUB_REPLY — Replace with AI-generated draft reply aligned to Brand Brain tone of voice.',
  escalation_required: false,
  escalation_reason: null,
  human_review_required: true,
  approval_status: 'Draft',
  created_by_agent: 'n8n-comment-inbox-reply-assistant (STUB)',
  created_at: new Date().toISOString(),
  notes: 'Phase 8 skeleton stub. No real AI call. human_review_required=true always. Owner must review before sending.'
};

return [{ json: { ...inputData, replyDraft, aiCallCompleted: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Write structured log entry per schemas/log-entry.schema.json
// PRODUCTION: Append to Google Sheets log tab or Supabase logs table
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL

const inputData = $input.first().json;
const reply = inputData.replyDraft || {};
const isEscalated = inputData.escalation_required === true;

const logEntry = {
  log_id: 'LOG-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-STUB-001',
  timestamp: new Date().toISOString(),
  phase: '8',
  agent_name: 'n8n-comment-inbox-reply-assistant (STUB)',
  action_type: 'Reply Draft',
  input_ref: inputData.channel || 'STUB_INPUT',
  output_ref: reply.reply_id || (isEscalated ? 'ESCALATED_NO_DRAFT' : 'STUB_OUTPUT'),
  status: 'Success',
  summary: isEscalated
    ? 'Inbox Reply skeleton: escalation_required=true. No draft generated. Owner must handle directly.'
    : 'Inbox Reply skeleton: draft created. human_review_required=true. No reply sent.',
  errors: null,
  next_action: isEscalated
    ? 'Owner to handle escalated message directly. Do not use AI draft.'
    : 'Owner to review draft reply before sending.',
  owner_action_required: isEscalated
};

return [{ json: { ...inputData, logEntry, logWritten: true } }];
